# runtime module: common

import json
import re




def decode(value):

    if isinstance(value, str):
        text = value.strip()
        if text[:1] in ("[", "{"):
            try:
                return json.loads(text)
            except Exception:
                return value
    return value


def walk(value, parts):

    for part in parts:
        value = decode(value)
        if isinstance(value, dict) and part in value:
            value = value.get(part)
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def lookup(state, key):





    if not isinstance(state, dict) or key is None:
        return None
    key = str(key)
    if key in state:
        return state.get(key)
    parts = key.split(".")
    cut = len(parts) - 1
    while cut > 0:
        head = ".".join(parts[:cut])
        if head in state:
            found, value = walk(state.get(head), parts[cut:])
            if found:
                return value
        cut -= 1
    return None
















































def as_text(value):

    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, float):
        try:
            if value == int(value):
                return str(int(value))
        except Exception:
            return str(value)
    return str(value)











































































# runtime module: products













MAX_ITEMS = 100


def as_items(value, list_field):

    value = decode(value)
    if isinstance(value, dict):
        inner = decode(value.get("data"))
        holder = inner if isinstance(inner, dict) else value
        value = decode(holder.get(list_field))
    if not isinstance(value, list):
        return []
    items = [decode(x) for x in value]
    return [x for x in items if isinstance(x, dict)]


def flat_items(state, base, cfg):

    items = []
    for index in range(MAX_ITEMS):
        prefix = base + "." + str(index) + "."
        if lookup(state, prefix + cfg["id_field"]) is None:
            break
        item = dict()
        for name in cfg.get("item_fields", []):
            value = lookup(state, prefix + name)
            if value is not None:
                item[name] = value
        items.append(item)
    return items


def scan_items(state, cfg):

    marker = "." + cfg["list_field"] + ".0." + cfg["id_field"]
    for key in list(state.keys()):
        items = as_items(state.get(key), cfg["list_field"])
        if items and items[0].get(cfg["id_field"]) is not None:
            return items
        if str(key).endswith(marker):
            items = flat_items(state, str(key)[:len(str(key)) - len(".0." + cfg["id_field"])], cfg)
            if items:
                return items
    return []


def find_items(state, cfg):

    for key in cfg.get("sources", []):
        items = as_items(lookup(state, key), cfg["list_field"])
        if items:
            return items
    for key in cfg.get("sources", []):
        items = flat_items(state, key, cfg)
        if items:
            return items
    return scan_items(state, cfg)

















































































































































































# runtime module: lists











def item_line(index, item, fields):

    parts = []
    for name in fields:
        if name in item:
            parts.append(name + ": " + as_text(item.get(name)))
    return str(index) + ". " + "; ".join(parts)


def run_list(state, cfg):

    var = cfg.get("var", "bb_list")
    try:
        items = find_items(state, cfg)
        lines = [item_line(i + 1, items[i], cfg.get("item_fields", [])) for i in range(len(items))]
        state[var] = "\n".join(lines) if lines else cfg.get("empty", "")
        state[var + "_count"] = len(items)
    except Exception as error:
        state[var] = cfg.get("empty", "")
        state[var + "_count"] = 0
        state["bb_list_error"] = str(error)

